def _lint_read_text(path):
    """ONE O_NONBLOCK descriptor, fstat-checked S_ISREG, strict UTF-8: the lint itself must never
    block on (or accept) a special file planted at a module path."""
    fd = os.open(path, os.O_RDONLY | getattr(os, "O_NONBLOCK", 0) | getattr(os, "O_CLOEXEC", 0))
    try:
        if not stat.S_ISREG(os.fstat(fd).st_mode):
            raise OSError("{}: refused, not a regular file".format(path))
        chunks = []
        while True:
            chunk = os.read(fd, 1 << 20)
            if not chunk:
                break
            chunks.append(chunk)
    finally:
        os.close(fd)
    return b"".join(chunks).decode("utf-8")


def _lint_source_lines(text):
    """The physical source lines of text by PYTHON SOURCE LINE SEMANTICS (round 10, decided
    4): an AST line number counts only LF, CRLF and CR line endings, while str.splitlines
    also breaks on U+2028, U+2029, form feed, U+0085 and the other Unicode separators, so a
    module holding one of those inside a string literal would shift every later finding off
    its physical line: the pin text behind an existing RAW_READ_UNSUPPORTED_USES key would
    then be taken from the WRONG line, and a changed finding line could keep an unrelated
    pin. Those separators stay INSIDE a physical line here."""
    return re.split("\r\n|\r|\n", text)


