def _raw_read_vector_failures():
    """The labels of _RAW_READ_VECTORS rows the CURRENT raw-read functions no longer satisfy,
    empty when every vector holds. The normal self-test requires it empty; the red-on-revert
    loop execs this same battery inside each _RAW_READ_REVERTS production mutant and requires
    EXACTLY the designated labels red, so each surviving round-4/5 leg (the fail-closed
    reference scan, the loader tokenizers), each round-6 leg (unconditional os.open
    counting, the star-import refusal) and each round-9 leg (every positional finding rule,
    the import-under-another-name refusals on each side, the direct-call token legs, the
    <no-py-literal> fallback and the from-subprocess launcher-name tracking) is shown
    load-bearing (decided 3: each refused position is red under the mutant that re-admits
    it, and the direct-call controls stay clean)."""
    failures = []
    for kind, label, source, expected in _RAW_READ_VECTORS:
        if kind == "sites":
            ok = _raw_read_sites(ast.parse(source)) == dict(expected)
        elif kind == "hits":
            ok = _raw_read_dynamic_edge_hits(ast.parse(source)) == dict(expected)
        else:
            # round 12 (decided 2): a "lines" row holds the finding LINES of both
            # scanners over the source, with the source supplied as the lint does
            rows = []
            _raw_read_sites(ast.parse(source), rows, source)
            _raw_read_dynamic_edge_hits(ast.parse(source), rows, source)
            ok = tuple(sorted(lineno for lineno, _note in rows)) == tuple(expected)
        if not ok:
            failures.append(label)
    return failures


def _raw_read_lint_pin_wiring_failures():
    """The labels of the lint-root fixture expectations the CURRENT _raw_read_lint no longer
    satisfies, empty when every one holds (round 10, decided 3 and 4): the fixture drives ONE
    unpinned unsupported-use finding and the stale-pin report through _raw_read_lint ITSELF
    (never only through _raw_read_use_pin_failures), and the unpinned report must quote the
    TRUE physical line even though an earlier string literal holds U+2028, which
    str.splitlines would treat as a line break. Red with the RAW_READ_UNSUPPORTED_USES
    application line removed from _raw_read_lint, and red with _lint_source_lines weakened
    back to splitlines."""
    failed = []
    with tempfile.TemporaryDirectory(prefix="aiqt-raw-read-lint-fixture-") as fixture_tmp:
        fixture_root = Path(fixture_tmp)
        for rel in (_RAW_READ_REGISTRATIONS + _RAW_READ_HOOK_SCRIPTS
                    + (_RAW_READ_SUITE_MANIFEST,)):
            (fixture_root / rel).parent.mkdir(parents=True, exist_ok=True)
            (fixture_root / rel).write_text("", encoding="utf-8")
        (fixture_root / ".preview").mkdir()
        (fixture_root / "tools" / "run_all_checks.sh").write_text(
            "python3 -I -B tools/entry_pin.py" + chr(10), encoding="utf-8")
        (fixture_root / "tools" / "entry_pin.py").write_text(
            "import os" + chr(10) + "x = " + chr(34) + chr(0x2028) + chr(34)
            + chr(10) + "saved = os.open" + chr(10) + "def fin(" + chr(10)
            + " os," + chr(10) + "): pass" + chr(10)
            + "def gl():" + chr(10) + "    global a, " + chr(92) + chr(10)
            + "        open" + chr(10)
            + "def gs():" + chr(10) + "    global b, " + chr(92) + chr(10)
            + "        subprocess" + chr(10), encoding="utf-8")
        failures, _stats = _raw_read_lint(fixture_root)
        if not any("tools/entry_pin.py" in failure
                   and "unsupported use of a watched name" in failure
                   for failure in failures):
            failed.append("raw-read-lint-fixture-unpinned-reported")
        needle = "line {!r};".format("saved = os.open")
        if not any(needle in failure for failure in failures):
            failed.append("raw-read-lint-fixture-unicode-line-text")
        if not any("stale RAW_READ_UNSUPPORTED_USES entry" in failure
                   for failure in failures):
            failed.append("raw-read-lint-fixture-stale-reported")
        # round 11 (decided 5): the fixture def spans three physical lines with the
        # watched parameter on the SECOND, so the unpinned report must quote the
        # parameter line, never the def line; red with the identifier location
        # dropped back to the holding node.
        if not any("line {!r};".format("os,") in failure for failure in failures):
            failed.append("raw-read-lint-fixture-ident-param-line")
        # round 12 (decided 2): a global name on a backslash-continued line is
        # located in the source tokens, which _raw_read_lint must hand to BOTH
        # scanners: the open name is judged by the sites scanner and the subprocess
        # name by the dynamic one; each report must quote the name's own line
        if not any("line {!r};".format("open") in failure for failure in failures):
            failed.append("raw-read-lint-fixture-ident-global-sites-line")
        if not any("line {!r};".format("subprocess") in failure for failure in failures):
            failed.append("raw-read-lint-fixture-ident-global-dynamic-line")
    return failed


